raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R01-01",
   "status": "OK",
   "label": "만 19세 미만 실명의 개인 가입",
   "source": {
    "quote": "▪ 만 19세 미만 실명의 개인"
   },
   "condition": {
    "and": [
     {
      "op": ">=",
      "left": {
       "var": "customer.age"
      },
      "right": 0
     },
     {
      "op": "<=",
      "left": {
       "var": "customer.age"
      },
      "right": 19
     },
     {
      "op": "==",
      "left": {
       "var": "customer.holder_type"
      },
      "right": "INDIVIDUAL"
     }
    ]
   },
   "effect": {
    "type": "REQUIRE",
    "value": "REAL_NAME"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R01-02",
   "status": "OK",
   "label": "개인사업자 및 임의단체 가입 불가",
   "source": {
    "quote": "※ 개인사업자 및 서류미제출 임의단체, 공동명의 가입 불가"
   },
   "condition": {
    "not": {
     "in": [
      {
       "var": "customer.holder_type"
      },
      [
       "INDIVIDUAL"
      ]
     ]
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R01-03",
   "status": "OK",
   "label": "1인 1계좌",
   "source": {
    "quote": "※「KB Young Youth 청소년통장」을 포함하여 1인 1계좌"
   },
   "condition": {
    "exists": {
     "event": "PRODUCT_SWITCH",
     "where": {
      "PRODUCT_SWITCH.direction": "IN"
     }
    },
    "and": {
     "op": "!=",
     "left": {
      "var": "customer.has_product"
     },
     "right": false
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  }
 ]
}

