raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R04-01",
   "status": "OK",
   "label": "연령 만 19세 자동전환",
   "source": {
    "quote": "▪ 매년 첫 영업일에 가입자의 연령이 만 19세인 경우 「KB국민ONE통장」으로 자동전환"
   },
   "let": {
    "window": {
     "year_range": {
      "from": {
       "anchor": "contract.switch_date",
       "offset_years": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.switch_date",
       "offset_years": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "var": "customer.age"
       },
       19
      ]
     },
     {
      "exists": {
       "event": "PRODUCT_SWITCH",
       "within": {
        "ref": "$window"
       }
      }
     }
    ]
   },
   "effect": {
    "type": "PRODUCT_SWITCH_TO",
    "value": "KB국민ONE통장"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R04-02",
   "status": "OK",
   "label": "KB국민ONE통장 보유 시 자동전환",
   "source": {
    "quote": "※ 단, KB국민ONE통장을 이미 보유하고 있는 경우에는 「KB종합통장」으로 자동전환"
   },
   "condition": {
    "in": [
     {
      "var": "customer.held_products"
     },
     [
      "KB국민ONE통장"
     ]
    ]
   },
   "effect": {
    "type": "PRODUCT_SWITCH_TO",
    "value": "KB종합통장"
   }
  }
 ]
}

